    <h1>Entrar</h1>
    <p class="subtitulo">Acesse seu extrato com segurança.</p>

    <form action="/entrar" method="post">
      <p id="erro-login" class="erro" role="alert" hidden>
        E-mail ou senha inválidos. Verifique os dados e tente novamente.
      </p>

      <div class="campo">
        <label for="email">E-mail</label>
        <input
          id="email"
          name="email"
          type="email"
          autocomplete="username"
          placeholder="voce@exemplo.com.br"
          aria-describedby="ajuda-email erro-login"
          required
        >
        <p id="ajuda-email" class="ajuda">Use o e-mail cadastrado na sua conta.</p>
      </div>

      <div class="campo">
        <label for="senha">Senha</label>
        <div class="senha-wrap">
          <input
            id="senha"
            name="senha"
            type="password"
            autocomplete="current-password"
            aria-describedby="erro-login"
            required
          >
          <button
            id="mostrar-senha"
            class="mostrar"
            type="button"
            aria-label="Mostrar senha"
            aria-controls="senha"
          >Mostrar</button>
        </div>
      </div>

      <button class="btn-entrar" type="submit">Entrar</button>

      <a class="recuperar" href="/recuperar">Esqueci minha senha</a>
    </form>
  </main>

  <script>
    (function () {
      var botao = document.getElementById('mostrar-senha');
      var campo = document.getElementById('senha');

      botao.addEventListener('click', function () {
        var mostrando = campo.type === 'password';
        campo.type = mostrando ? 'text' : 'password';
        botao.textContent = mostrando ? 'Ocultar' : 'Mostrar';
        botao.setAttribute('aria-label', mostrando ? 'Ocultar senha' : 'Mostrar senha');
      });
    })();
  </script>
</body>
</html>
