  <script>
    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var emailErro = document.getElementById('email-erro');
      var senhaErro = document.getElementById('senha-erro');
      var toggle = document.querySelector('.toggle-password');

      function mostrarErro(campo, erroEl, mensagem) {
        if (mensagem) {
          erroEl.textContent = mensagem;
          erroEl.hidden = false;
          campo.setAttribute('aria-invalid', 'true');
        } else {
          erroEl.textContent = '';
          erroEl.hidden = true;
          campo.removeAttribute('aria-invalid');
        }
      }

      function validarEmail() {
        if (!email.value.trim()) return 'Informe seu e-mail.';
        if (!email.validity.valid) return 'Informe um e-mail válido, como nome@exemplo.com.';
        return '';
      }

      function validarSenha() {
        if (!senha.value) return 'Informe sua senha.';
        return '';
      }

      form.addEventListener('submit', function (event) {
        var erroEmail = validarEmail();
        var erroSenha = validarSenha();
        mostrarErro(email, emailErro, erroEmail);
        mostrarErro(senha, senhaErro, erroSenha);
        if (erroEmail || erroSenha) {
          event.preventDefault();
          (erroEmail ? email : senha).focus();
        }
      });

      email.addEventListener('input', function () {
        if (email.getAttribute('aria-invalid')) mostrarErro(email, emailErro, validarEmail());
      });

      senha.addEventListener('input', function () {
        if (senha.getAttribute('aria-invalid')) mostrarErro(senha, senhaErro, validarSenha());
      });

      toggle.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        toggle.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      });
    })();
  </script>
